"403 :     protected PointValuePair getSolution() {
404 :       int negativeVarColumn = columnLabels.indexOf(NEGATIVE_VAR_COLUMN_LABEL);
405 :       Integer negativeVarBasicRow = negativeVarColumn > 0 ? getBasicRow(negativeVarColumn) : null;
406 :       double mostNegative = negativeVarBasicRow == null ? 0 : getEntry(negativeVarBasicRow, getRhsOffset());
407 : 
408 :       Set<Integer> basicRows = new HashSet<Integer>();
409 :       double[] coefficients = new double[getOriginalNumDecisionVariables()];
410 :       for (int i = 0; i < coefficients.length; i++) {
411 :           int colIndex = columnLabels.indexOf("x" + i);
412 :           if (colIndex < 0) {
413 :             coefficients[i] = 0;
414 :             continue;
415 :           }
416 :           Integer basicRow = getBasicRow(colIndex);
417 :           if (basicRow != null && basicRow == 0) {
418 :               // if the basic row is found to be the objective function row
419 :               // set the coefficient to 0 -> this case handles unconstrained
420 :               // variables that are still part of the objective function
421 :               coefficients[i] = 0;
422 :           } else if (basicRows.contains(basicRow)) {
423 :               // if multiple variables can take a given value
424 :               // then we choose the first and set the rest equal to 0
425 :               coefficients[i] = 0 - (restrictToNonNegative ? 0 : mostNegative);
426 :           } else {
427 :               basicRows.add(basicRow);
428 :               coefficients[i] =
429 :                   (basicRow == null ? 0 : getEntry(basicRow, getRhsOffset())) -
430 :                   (restrictToNonNegative ? 0 : mostNegative);
431 :           }
432 :       }
433 :       return new PointValuePair(coefficients, f.getValue(coefficients));
434 :     }"

